def comps(grid):
 R,C=len(grid),len(grid[0]); seen=set(); out=[]
 for r in range(R):
  for c in range(C):
   if grid[r][c] in (4,8) and (r,c) not in seen:
    col=grid[r][c]; q=[(r,c)];seen.add((r,c)); pts=[]
    while q:
     a,b=q.pop();pts.append((a,b))
     for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
      if 0<=x<R and 0<=y<C and grid[x][y]==col and (x,y) not in seen:seen.add((x,y));q.append((x,y))
    rs=[a for a,b in pts];cs=[b for a,b in pts]
    out.append((col,len(pts),(min(rs),max(rs),min(cs),max(cs)),len(pts)==(max(rs)-min(rs)+1)*(max(cs)-min(cs)+1)))
 return sorted(out,key=lambda x:(x[0],x[2]))
